const overviewTodayOperations = `-- name: OverviewTodayOperations :many
SELECT t.uuid, t.task_type, t.status, t.due_at, t.completed_at,
    b.uuid AS branch_uuid, b.code AS branch_code, b.name AS branch_name,
    r.uuid AS rental_uuid, r.reference AS rental_reference, r.status AS rental_status,
    res.uuid AS reservation_uuid,
    COALESCE(tv.plate, rv.plate, '')::text AS vehicle_plate,
    c.customer_type, c.first_name AS customer_first_name, c.last_name AS customer_last_name,
    c.company_title AS customer_company_title,
    COUNT(*) OVER ()::bigint AS total
FROM operation_tasks t
JOIN branches b ON b.organization_id = t.organization_id AND b.id = t.branch_id
JOIN rentals r ON r.organization_id = t.organization_id AND r.id = t.rental_id
JOIN reservations res ON res.organization_id = r.organization_id AND res.id = r.reservation_id
JOIN customers c ON c.organization_id = res.organization_id AND c.id = res.customer_id
LEFT JOIN vehicles tv ON tv.organization_id = t.organization_id AND tv.id = t.vehicle_id
LEFT JOIN vehicles rv ON rv.organization_id = r.organization_id AND rv.id = r.vehicle_id
WHERE t.organization_id = $1
  AND b.organization_id = $1
  AND r.organization_id = $1
  AND res.organization_id = $1
  AND c.organization_id = $1
  AND t.task_type IN ('handover', 'return')
  AND t.status <> 'cancelled'
  AND t.due_at >= $2::timestamptz
  AND t.due_at < $3::timestamptz
  AND ($4::bigint[] IS NULL OR t.branch_id = ANY($4::bigint[]))
ORDER BY t.due_at, t.id
LIMIT $5
`

type OverviewTodayOperationsParams struct {
	OrganizationID int64              `json:"organization_id"`
	DayStart       pgtype.Timestamptz `json:"day_start"`
	DayEnd         pgtype.Timestamptz `json:"day_end"`
	BranchIds      []int64            `json:"branch_ids"`
	LimitCount     int32              `json:"limit_count"`
}

type OverviewTodayOperationsRow struct {
	Uuid                 uuid.UUID          `json:"uuid"`
	TaskType             string             `json:"task_type"`
	Status               string             `json:"status"`
	DueAt                pgtype.Timestamptz `json:"due_at"`
	CompletedAt          pgtype.Timestamptz `json:"completed_at"`
	BranchUuid           uuid.UUID          `json:"branch_uuid"`
	BranchCode           string             `json:"branch_code"`
	BranchName           string             `json:"branch_name"`
	RentalUuid           uuid.UUID          `json:"rental_uuid"`
	RentalReference      string             `json:"rental_reference"`
	RentalStatus         string             `json:"rental_status"`
	ReservationUuid      uuid.UUID          `json:"reservation_uuid"`
	VehiclePlate         string             `json:"vehicle_plate"`
	CustomerType         string             `json:"customer_type"`
	CustomerFirstName    string             `json:"customer_first_name"`
	CustomerLastName     string             `json:"customer_last_name"`
	CustomerCompanyTitle string             `json:"customer_company_title"`
	Total                int64              `json:"total"`
}

// Handover and return tasks due in [day_start, day_end) of the task's
// branch (operation task rule), with the rental, plate and customer.
func (q *Queries) OverviewTodayOperations(ctx context.Context, arg OverviewTodayOperationsParams) ([]OverviewTodayOperationsRow, error) {
	rows, err := q.db.Query(ctx, overviewTodayOperations,
		arg.OrganizationID,
		arg.DayStart,
		arg.DayEnd,
		arg.BranchIds,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OverviewTodayOperationsRow{}
	for rows.Next() {
		var i OverviewTodayOperationsRow
		if err := rows.Scan(
			&i.Uuid,
			&i.TaskType,
			&i.Status,
			&i.DueAt,
			&i.CompletedAt,
			&i.BranchUuid,
			&i.BranchCode,
			&i.BranchName,
			&i.RentalUuid,
			&i.RentalReference,
			&i.RentalStatus,
			&i.ReservationUuid,
			&i.VehiclePlate,
			&i.CustomerType,
			&i.CustomerFirstName,
			&i.CustomerLastName,
			&i.CustomerCompanyTitle,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const overviewWaitingReservations = `-- name: OverviewWaitingReservations :many
SELECT r.uuid, r.reference, r.status, r.starts_at, r.ends_at, r.channel, r.review_deadline, r.payment_deadline,
    r.currency, r.total_amount, r.prepayment_amount, r.paid_amount,
    pb.uuid AS pickup_branch_uuid, pb.code AS pickup_branch_code, pb.name AS pickup_branch_name,
    c.customer_type, c.first_name AS customer_first_name, c.last_name AS customer_last_name,
    c.company_title AS customer_company_title,
    COUNT(*) OVER ()::bigint AS total,
    (COUNT(*) FILTER (
        WHERE COALESCE(CASE WHEN r.status = 'awaiting_payment' THEN r.payment_deadline ELSE r.review_deadline END,
            'infinity'::timestamptz) < $1::timestamptz
    ) OVER ())::bigint AS overdue
FROM reservations r
JOIN branches pb ON pb.organization_id = r.organization_id AND pb.id = r.pickup_branch_id
JOIN customers c ON c.organization_id = r.organization_id AND c.id = r.customer_id
WHERE r.organization_id = $2
  AND pb.organization_id = $2
  AND c.organization_id = $2
  AND r.status = ANY($3::text[])
  AND (
    $4::bigint[] IS NULL
    OR r.pickup_branch_id = ANY($4::bigint[])
    OR r.return_branch_id = ANY($4::bigint[])
  )
ORDER BY CASE WHEN r.status = 'awaiting_payment' THEN r.payment_deadline ELSE r.review_deadline END ASC NULLS LAST,
    r.starts_at, r.id
LIMIT $5
`

type OverviewWaitingReservationsParams struct {
	Now            pgtype.Timestamptz `json:"now"`
	OrganizationID int64              `json:"organization_id"`
	Statuses       []string           `json:"statuses"`
	BranchIds      []int64            `json:"branch_ids"`
	LimitCount     int32              `json:"limit_count"`
}

type OverviewWaitingReservationsRow struct {
	Uuid                 uuid.UUID          `json:"uuid"`
	Reference            string             `json:"reference"`
	Status               string             `json:"status"`
	StartsAt             pgtype.Timestamptz `json:"starts_at"`
	EndsAt               pgtype.Timestamptz `json:"ends_at"`
	Channel              string             `json:"channel"`
	ReviewDeadline       pgtype.Timestamptz `json:"review_deadline"`
	PaymentDeadline      pgtype.Timestamptz `json:"payment_deadline"`
	Currency             string             `json:"currency"`
	TotalAmount          pgtype.Numeric     `json:"total_amount"`
	PrepaymentAmount     pgtype.Numeric     `json:"prepayment_amount"`
	PaidAmount           pgtype.Numeric     `json:"paid_amount"`
	PickupBranchUuid     uuid.UUID          `json:"pickup_branch_uuid"`
	PickupBranchCode     string             `json:"pickup_branch_code"`
	PickupBranchName     string             `json:"pickup_branch_name"`
	CustomerType         string             `json:"customer_type"`
	CustomerFirstName    string             `json:"customer_first_name"`
	CustomerLastName     string             `json:"customer_last_name"`
	CustomerCompanyTitle string             `json:"customer_company_title"`
	Total                int64              `json:"total"`
	Overdue              int64              `json:"overdue"`
}

// Reservations in the given statuses (approval queue: request,
// awaiting_review; waiting for payment: awaiting_payment), soonest
// deadline first. Reservation rule: pick-up or return branch in the
// filter. overdue = deadline passed.
func (q *Queries) OverviewWaitingReservations(ctx context.Context, arg OverviewWaitingReservationsParams) ([]OverviewWaitingReservationsRow, error) {
	rows, err := q.db.Query(ctx, overviewWaitingReservations,
		arg.Now,
		arg.OrganizationID,
		arg.Statuses,
		arg.BranchIds,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OverviewWaitingReservationsRow{}
	for rows.Next() {
		var i OverviewWaitingReservationsRow
		if err := rows.Scan(
			&i.Uuid,
			&i.Reference,
			&i.Status,
			&i.StartsAt,
			&i.EndsAt,
			&i.Channel,
			&i.ReviewDeadline,
			&i.PaymentDeadline,
			&i.Currency,
			&i.TotalAmount,
			&i.PrepaymentAmount,
			&i.PaidAmount,
			&i.PickupBranchUuid,
			&i.PickupBranchCode,
			&i.PickupBranchName,
			&i.CustomerType,
			&i.CustomerFirstName,
			&i.CustomerLastName,
			&i.CustomerCompanyTitle,
			&i.Total,
			&i.Overdue,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
